const openImages=new Map();let openCameraKey='';function drawOpenSpace(){const z=openSpaces[state.zone],[cx,cy]=spaceCamera(state.zone,[state.x,state.y]);const imageKey=state.zone==='elevator'?'elevator-'+state.elevator.deck:state.zone;if(!openImages.has(imageKey)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(state.zone==='elevator'?elevatorBackdrop(state.elevator.deck):openSpaceSvg(state.zone));openImages.set(imageKey,img);}const img=openImages.get(imageKey);ctx.fillStyle=z.color;ctx.fillRect(0,0,1000,600);if(img.complete&&img.naturalWidth)ctx.drawImage(img,-cx,-cy,z.width,z.height);if(state.zone==='diglands'){ctx.fillStyle='#203440';for(const cell of state.openWorld.cleared){const [x,y]=cell.split(',').map(Number);if(x*40-cx>-40&&x*40-cx<1000&&y*40-cy>-40&&y*40-cy<600)ctx.fillRect(x*40-cx,y*40-cy,40,40);}}if(state.zone==='elevator')drawElevatorCompanions();if(chapterWorlds[state.zone]){ctx.fillStyle='#203440';for(const cell of state.chapter.cleared[state.zone]){const [x,y]=cell.split(',').map(Number);ctx.fillRect(x*40-cx,y*40-cy,40,40);}drawChapterProps(cx,cy);}
ctx.fillStyle='#12394c';ctx.fillRect(0,0,1000,95);ctx.fillStyle='#fffbed';ctx.font='bold 22px system-ui';ctx.fillText(z.name.toUpperCase(),25,52);const key=state.zone+'/'+Math.round(cx)+'/'+Math.round(cy);if(key!==openCameraKey){openCameraKey=key;const camera=[cx,cy];for(const b of document.querySelectorAll('#targets [data-id]')){const o=objects.find(o=>o.id===b.dataset.id);if(!o)continue;const x=o.x-camera[0],y=o.y-camera[1];b.style.left=x/10+'%';b.style.top=y/6+'%';b.hidden=x<45||x>955||y<130||y>490;}}}

